  236	// Snapshot writes every user and reminder to w as JSON.
  237	func (s *Store) Snapshot(w io.Writer) error {
  238		s.mu.RLock()
  239		defer s.mu.RUnlock()
  240		type reminder struct {
  241			*Reminder
  242			Rule string `json:",omitempty"`
  243		}
  244		snap := struct {
  245			Users     []*User
  246			Reminders []reminder
  247		}{}
  248		for _, u := range s.users {
  249			snap.Users = append(snap.Users, u)
  250		}
  251		slices.SortFunc(snap.Users, func(a, b *User) int { return cmp.Compare(a.ID, b.ID) })
  252		for _, r := range s.reminders {
  253			rr := reminder{Reminder: r}
  254			if r.Rule != nil {
  255				rr.Rule = r.Rule.String()
  256			}
  257			snap.Reminders = append(snap.Reminders, rr)
  258		}
  259		slices.SortFunc(snap.Reminders, func(a, b reminder) int { return cmp.Compare(a.ID, b.ID) })
  260		if err := json.NewEncoder(w).Encode(snap); err != nil {
  261			return fmt.Errorf("store: snapshot: %w", err)
  262		}
  263		return nil
  264	}

